  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED established a powerful new regime for controlling and measuring light–matter interactions, and became a central experimental platform for quantum physics.",
        "attribution": "Blais's theoretical proposal and Wallraff's and Schoelkopf's experimental contributions capture the proposal-to-platform arc. Steven M. Girvin's foundational theoretical contributions make a three-person attribution difficult.",
        "maturity": "The platform has been explored and reproduced across many laboratories for two decades, with a substantial body of results beyond computing applications.",
        "uncertainties": [
          "The discovery boundary and credit among theorists and experimentalists need careful definition."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed that quantum information can in principle be protected against noise, resolving a central conceptual obstacle to quantum computation and enabling a broad field.",
        "attribution": "Shor and Steane developed seminal codes, while Kitaev's topological approach opened a distinct route to fault tolerance; the proposed names represent complementary foundational contributions.",
        "maturity": "The theoretical framework is established and experimental demonstrations have advanced substantially, though large-scale fault-tolerant computing remains unachieved.",
        "uncertainties": [
          "The scope combines several distinct contributions, and practical fault tolerance is still under development."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mikhail D. Lukin",
        "Mark Saffman"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade and programmable neutral-atom arrays made strongly interacting, individually controlled many-body quantum systems experimentally accessible, with major value for both fundamental studies and simulation.",
        "attribution": "Browaeys and Lukin helped establish the interacting-array platform; Saffman's work on blockade and neutral-atom control is also central. The field has broad contributions beyond these names.",
        "maturity": "The platform has developed rapidly and has been independently pursued by multiple groups, but its most ambitious many-body and computational claims are relatively recent.",
        "uncertainties": [
          "The field's defining achievement and the relative weight of blockade, array control, and later applications remain unsettled."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices created a clean and tunable setting for studying quantum many-body physics, including Hubbard-model phenomena that are difficult to access in solids.",
        "attribution": "Bloch and Greiner made landmark experimental contributions, while Zoller developed influential theoretical foundations. Juan Ignacio Cirac is also a major contributor, making a three-person limit consequential.",
        "maturity": "The platform and its core capabilities are well established across laboratories, although fully resolving questions such as high-temperature superconductivity remains a work in progress.",
        "uncertainties": [
          "It is not yet clear which specific result within the broad quantum-simulation program should define the prize."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B044",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping by enabling exceptionally accurate and stable atomic references, with direct relevance to tests of fundamental physics.",
        "attribution": "Katori and Ye independently established key approaches and led influential experimental programs; the two-person attribution is comparatively clear.",
        "maturity": "The clocks are mature, repeatedly realized, and continue to improve, with demonstrated applications in precision measurement.",
        "uncertainties": [
          "The balance between fundamental discovery and the precision-instrument achievement should be weighed."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B036",
      "proposed_laureates": [
        "Charles H. Bennett",
        "Gilles Brassard",
        "Artur Ekert"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum cryptography turned nonclassical correlations and measurement principles into a new, experimentally testable approach to secure communication.",
        "attribution": "Bennett and Brassard established the influential BB84 protocol, while Ekert introduced an entanglement-based approach; these contributions are distinct and identifiable.",
        "maturity": "The theory is established and demonstrations span decades, although practical deployments still face engineering and security constraints.",
        "uncertainties": [
          "The award would need to distinguish foundational physics from the later development of communication protocols and technology."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov–Bohm effect and Berry phase revealed that quantum phases and potentials have observable consequences beyond classical field-based intuition, influencing many areas of physics.",
        "attribution": "Aharonov is associated with the effect and Berry with the geometric phase; the two results are related in significance but historically and conceptually distinct.",
        "maturity": "Both ideas have been experimentally confirmed and used extensively, though their foundational discoveries date back several decades.",
        "uncertainties": [
          "Combining two major but separate discoveries under one citation could obscure their individual histories."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Juan Maldacena",
        "Edward Witten",
        "Alexander Polyakov"
      ],
      "assessment": {
        "nobel_worthiness": "Gauge/gravity duality is a profound theoretical connection that has reshaped approaches to quantum gravity and strongly coupled field theory.",
        "attribution": "Maldacena formulated the concrete duality, with Witten and Polyakov providing major related foundations and developments; credit for the broad framework is distributed.",
        "maturity": "The correspondence is mathematically influential and widely applied, but direct empirical confirmation as a description of nature is lacking.",
        "uncertainties": [
          "The absence of direct experimental tests makes its standing as a physics discovery less settled."
        ]
      }
    }
  ]
}
